import{_ as e,o as a,c as t,a5 as c}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"01 — Cấu trúc tổ chức: Agency / Workspace / Role","description":"","frontmatter":{},"headers":[],"relativePath":"ba/01-organization-structure.md","filePath":"ba/01-organization-structure.md"}'),i={name:"ba/01-organization-structure.md"};function o(r,n,h,g,l,s){return a(),t("div",null,[...n[0]||(n[0]=[c(`<h1 id="_01-—-cau-truc-to-chuc-agency-workspace-role" tabindex="-1">01 — Cấu trúc tổ chức: Agency / Workspace / Role <a class="header-anchor" href="#_01-—-cau-truc-to-chuc-agency-workspace-role" aria-label="Permalink to &quot;01 — Cấu trúc tổ chức: Agency / Workspace / Role&quot;">​</a></h1><p>&gt; <a href="./00-overview.html">&lt;&lt; Về Overview</a></p><h2 id="_1-mo-hinh-tong-quan" tabindex="-1">1. Mô hình tổng quan <a class="header-anchor" href="#_1-mo-hinh-tong-quan" aria-label="Permalink to &quot;1. Mô hình tổng quan&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User</span></span>
<span class="line"><span> └─ là OWNER của N Agency (1 user có thể sở hữu nhiều Agency)</span></span>
<span class="line"><span>     Agency</span></span>
<span class="line"><span>      ├─ có đúng 1 OWNER (gắn 1-1 với user tạo ra Agency)</span></span>
<span class="line"><span>      └─ Member (invite vào Agency — KHÔNG có role gì ở cấp này)</span></span>
<span class="line"><span>          └─ Workspace (1 Agency có N Workspace)</span></span>
<span class="line"><span>              ├─ OWNER / MANAGER / MEMBER — role GÁN RIÊNG theo TỪNG Workspace</span></span>
<span class="line"><span>              └─ CLIENT — actor ngoài Agency, được invite vào Workspace để theo dõi/duyệt</span></span></code></pre></div><p>Đây là thay đổi lớn nhất so với hệ thống cũ: cũ chỉ có <code>User → Workspace</code> 1 tầng, role cố định toàn cục (AGENCY_OWNER/MANAGER/CREATOR/CLIENT). Mới thêm hẳn 1 tầng <strong>Agency</strong> ở giữa, và role không còn cố định mà gán theo từng Workspace.</p><h2 id="_2-agency" tabindex="-1">2. Agency <a class="header-anchor" href="#_2-agency" aria-label="Permalink to &quot;2. Agency&quot;">​</a></h2><ul><li>Agency đại diện 1 công ty truyền thông (media agency) thật.</li><li>1 User có thể là Owner của nhiều Agency (FR 3.4.1 — List Agency: &quot;mỗi người dùng đều là chủ của các Agency nên họ có trang để list ra các Agency họ đang sở hữu&quot;).</li><li>Agency có <strong>đúng 1 OWNER</strong> — gắn 1-1 với user tạo ra nó (FR 3.4.3 Create Agency: &quot;có owner id được liên kết với id của một user duy nhất là người tạo ra agency đó&quot;).</li><li>Agency có Profile công khai (FR 3.4.4 View Agency Profile) — thông tin công ty để Client hiểu về Agency trước khi hợp tác.</li><li>Agency Dashboard (FR 3.4.2) — Owner xem thông tin tổng quan công ty.</li><li>Xóa Agency (FR 3.4.6) — <strong>soft delete</strong>, có confirm, khôi phục được trong 30 ngày.</li></ul><h3 id="member-trong-agency" tabindex="-1">Member trong Agency <a class="header-anchor" href="#member-trong-agency" aria-label="Permalink to &quot;Member trong Agency&quot;">​</a></h3><ul><li>Owner <strong>invite Member vào Agency</strong> qua email + notification (FR 3.4.7).</li><li>Member vừa được invite <strong>không có role gì trong Agency</strong> — chỉ là thành viên công ty thông thường, chưa có quyền quản lý cụ thể.</li><li>Lời mời (Agency Invitation) hiển thị cho cả người mời và người được mời thấy trạng thái, <strong>tự động hết hạn sau 3 ngày</strong> (FR 3.4.8).</li><li>Xóa Member khỏi Agency (FR 3.4.9 Remove Member): <ul><li>Member mất quyền truy cập tài nguyên Agency.</li><li><strong>Tài nguyên họ đã tạo ra khi còn trong Agency vẫn giữ nguyên</strong> — vì thuộc tài sản chung của Agency, không bị xóa theo người.</li><li>Nếu được thêm lại vào Agency sau đó, họ được chỉnh sửa/sử dụng tiếp các tài nguyên cũ đó.</li></ul></li></ul><h2 id="_3-workspace" tabindex="-1">3. Workspace <a class="header-anchor" href="#_3-workspace" aria-label="Permalink to &quot;3. Workspace&quot;">​</a></h2><ul><li>1 Agency có N Workspace.</li><li><strong>1 Workspace có thể phục vụ nhiều Client cùng lúc</strong> — KHÔNG phải mô hình 1 workspace = 1 client. Workspace giống 1 &quot;không gian dự án/team&quot; dùng chung tài nguyên nội bộ (Material Repository, Hashtag Collection, Chatbot riêng...).</li><li>List Workspace (FR 3.4.10): Member chỉ coi được workspace mình có mặt trong đó; <strong>Owner coi được toàn bộ workspace của Agency</strong>.</li><li>Workspace Dashboard (FR 3.4.11) — thông tin chung + thống kê của workspace.</li></ul><h3 id="tao-workspace-fr-3-4-12" tabindex="-1">Tạo Workspace (FR 3.4.12) <a class="header-anchor" href="#tao-workspace-fr-3-4-12" aria-label="Permalink to &quot;Tạo Workspace (FR 3.4.12)&quot;">​</a></h3><ul><li>Chỉ OWNER tạo được Workspace mới.</li><li><strong>Bắt buộc gán ít nhất 1 Manager ngay lúc tạo</strong> — người này có toàn quyền quản lý workspace đó.</li><li><strong>[CONFIRMED 2026-09-14]</strong> Owner tạo Workspace có thể <strong>tự gán mình làm Manager</strong> của workspace đó, <strong>hoặc gán 1 Member khác làm Manager</strong> — cả 2 tình huống đều hợp lệ, không bắt buộc theo 1 chiều.</li></ul><h3 id="workspace-profile-fr-3-4-13" tabindex="-1">Workspace Profile (FR 3.4.13) <a class="header-anchor" href="#workspace-profile-fr-3-4-13" aria-label="Permalink to &quot;Workspace Profile (FR 3.4.13)&quot;">​</a></h3><ul><li>Có field cực quan trọng: <strong>Timezone Configuration</strong> — định nghĩa mốc thời gian chuẩn hoạt động của workspace này.</li><li>Lý do: mỗi sự kiện tổ chức ở địa điểm khác nhau, mốc thời gian theo UTC/timezone riêng giúp bài viết đăng tối ưu theo giờ vàng của từng địa điểm làm truyền thông (viral tùy chỉnh theo địa điểm).</li><li>Update Workspace Profile (FR 3.4.14) — OWNER/MANAGER cùng có quyền update.</li></ul><h3 id="xoa-workspace-fr-3-4-15" tabindex="-1">Xóa Workspace (FR 3.4.15) <a class="header-anchor" href="#xoa-workspace-fr-3-4-15" aria-label="Permalink to &quot;Xóa Workspace (FR 3.4.15)&quot;">​</a></h3><ul><li><strong>Chỉ OWNER</strong> mới được xóa Workspace.</li><li>Soft delete — khôi phục được trong 30 ngày.</li><li>Khi xóa: toàn bộ Member/Client mất quyền truy cập, mọi dữ liệu trong workspace chuyển trạng thái <strong>inactive</strong>.</li></ul><h3 id="roi-workspace-fr-3-4-16" tabindex="-1">Rời Workspace (FR 3.4.16) <a class="header-anchor" href="#roi-workspace-fr-3-4-16" aria-label="Permalink to &quot;Rời Workspace (FR 3.4.16)&quot;">​</a></h3><ul><li>Member rời Workspace nhưng <strong>vẫn còn trong Agency</strong> — rời Workspace không đồng nghĩa rời Agency.</li></ul><h3 id="workspace-template-fr-3-4-17" tabindex="-1">Workspace Template (FR 3.4.17) <a class="header-anchor" href="#workspace-template-fr-3-4-17" aria-label="Permalink to &quot;Workspace Template (FR 3.4.17)&quot;">​</a></h3><ul><li>Owner lưu lại 1 workspace hiện có thành <strong>template</strong> (thông tin cơ bản + cách triển khai) để tái sử dụng khi tạo workspace mới sau này — tăng tốc setup cho các dự án tương tự.</li></ul><h3 id="quan-ly-member-trong-workspace-fr-3-4-18-–-3-4-21" tabindex="-1">Quản lý Member trong Workspace (FR 3.4.18 – 3.4.21) <a class="header-anchor" href="#quan-ly-member-trong-workspace-fr-3-4-18-–-3-4-21" aria-label="Permalink to &quot;Quản lý Member trong Workspace (FR 3.4.18 – 3.4.21)&quot;">​</a></h3><ul><li>View Workspace Members (FR 3.4.18) — mọi Member trong workspace xem được danh sách.</li><li>Add Workspace Member (FR 3.4.19) — OWNER/MANAGER thêm 1 Member <strong>đã có trong Agency</strong> vào Workspace với 1 role cụ thể.</li><li>Update Workspace Member Role (FR 3.4.20) — OWNER/MANAGER đổi role của Member trong chính workspace đó.</li><li>Remove Workspace Member (FR 3.4.21) — OWNER/MANAGER xóa Member khỏi Workspace (không xóa khỏi Agency).</li></ul><h2 id="_4-role-gan-theo-workspace-—-quy-tac-cot-loi" tabindex="-1">4. Role gán theo Workspace — quy tắc cốt lõi <a class="header-anchor" href="#_4-role-gan-theo-workspace-—-quy-tac-cot-loi" aria-label="Permalink to &quot;4. Role gán theo Workspace — quy tắc cốt lõi&quot;">​</a></h2><p><strong>[CONFIRMED 2026-09-14]</strong> Role hoàn toàn độc lập giữa các Workspace khác nhau trong cùng 1 Agency.</p><p>Ví dụ: User A có thể là:</p><ul><li><code>MANAGER</code> ở Workspace X (được Owner gán toàn quyền quản lý workspace đó),</li><li>nhưng chỉ là <code>MEMBER</code> thường (ví dụ Creator) ở Workspace Y — cùng thuộc 1 Agency, nhưng vai trò khác hẳn.</li></ul><p>Điều này khác biệt hoàn toàn với hệ thống cũ, nơi 1 role gắn cố định cho 1 user trong toàn hệ thống.</p><h2 id="_5-client-—-actor-ngoai-agency" tabindex="-1">5. Client — actor ngoài Agency <a class="header-anchor" href="#_5-client-—-actor-ngoai-agency" aria-label="Permalink to &quot;5. Client — actor ngoài Agency&quot;">​</a></h2><ul><li><strong>[CONFIRMED 2026-09-14]</strong> Client KHÔNG phải member nội bộ của Agency/Workspace theo nghĩa nhân sự công ty — là khách hàng thuê Agency thực hiện truyền thông.</li><li>Có <strong>Client Profile riêng</strong> (xem <a href="./02-authentication-profile.html">02-authentication-profile.md</a> mục Client Profile) — tái sử dụng được khi Client tham gia làm việc với nhiều Agency/Workspace khác nhau, không cần khai lại thông tin mỗi lần.</li><li>Được Manager <strong>invite vào 1 Workspace cụ thể</strong> để theo dõi tiến độ, đàm phán Package/Campaign, duyệt nội dung, kết nối social account của họ.</li><li>Không có quyền quản lý nội bộ Agency/Workspace (thêm/xóa member, đổi cấu hình...) — chỉ có quyền trong phạm vi nghiệp vụ: xem, request, approve/reject, comment.</li></ul><h2 id="_6-admin-—-tach-biet-hoan-toan-he-thong" tabindex="-1">6. Admin — tách biệt hoàn toàn hệ thống <a class="header-anchor" href="#_6-admin-—-tach-biet-hoan-toan-he-thong" aria-label="Permalink to &quot;6. Admin — tách biệt hoàn toàn hệ thống&quot;">​</a></h2><ul><li>Admin quản trị toàn hệ thống BrandHub — <strong>không thuộc Agency nào</strong>, không nằm trong cấu trúc Agency→Workspace.</li><li>Xem chi tiết tại <a href="./09-admin-management.html">09-admin-management.md</a>.</li></ul><h2 id="_7-thu-tu-nghiep-vu-lien-quan-tham-chieu" tabindex="-1">7. Thứ tự nghiệp vụ liên quan (tham chiếu) <a class="header-anchor" href="#_7-thu-tu-nghiep-vu-lien-quan-tham-chieu" aria-label="Permalink to &quot;7. Thứ tự nghiệp vụ liên quan (tham chiếu)&quot;">​</a></h2><p>Sau khi Workspace được tạo (mục 3 ở trên), bước tiếp theo là mời Client vào Workspace rồi đàm phán Media Package/Campaign — xem chi tiết đầy đủ tại <a href="./04-media-package-campaign.html">04-media-package-campaign.md</a>, mục &quot;Thứ tự chuẩn: Workspace → Package → Campaign&quot;.</p><p><strong>Điểm khác so với đọc thẳng câu chữ CSV gốc:</strong> FR 3.5.1 viết &quot;khi mà tạo Workspace bắt buộc phải có cái template media package&quot; — dễ đọc nhầm là Package phải tồn tại TRƯỚC khi Workspace được tạo. Thực tế đã confirm: <strong>Workspace tạo trước</strong>, Manager được gán ngay lúc tạo, sau đó Manager mới chọn Package template (điều kiện để workspace &quot;sẵn sàng&quot; trước khi mời Client vào, không phải điều kiện tiên quyết để được tạo workspace).</p>`,35)])])}const m=e(i,[["render",o]]);export{p as __pageData,m as default};
